  let isRight: boolean
  if (info.R === 2) {
    isRight = equal(rc4(key, PAD), info.U.subarray(0, 32))
  } else {
    let x = rc4(key, md5(concat(PAD, info.id)))
    for (let i = 1; i <= 19; i += 1) x = rc4(key.map(b => b ^ i), x)
    isRight = equal(x, info.U.subarray(0, 16))
